//! testdata/protx_collateral.json: two ProRegTx a v24 regtest dashd built
//! (`protx register_fund` with a collateral the transaction pays itself,
//! and `protx register_prepare` / `register_submit` with an existing one),
//! with `protx info`'s collateral, generated by
//! testdata/oracle/dashd/gen_masternode_vectors.py.

#![allow(non_snake_case)] // test names carry checklist ids

use std::str::FromStr;

use dashcore::blockdata::transaction::special_transaction::TransactionPayload;
use dashcore::blockdata::transaction::special_transaction::provider_registration::ProviderRegistrationPayload;
use dashcore::hashes::Hash;
use dashcore::{Address, Network, OutPoint, ScriptBuf, Transaction, Txid};
use dw_protx::bls::{legacy_of, parse_public_hex};
use dw_protx::params::MASTERNODE_COLLATERAL;
use dw_protx::payloads::{
    CollateralSource, RegistrationSigner, RegistrationTerms, finalize_registration,
    registration_placeholder, registration_sign_message, resolve_collateral, sign_message_compact,
};
use serde_json::Value;
use zeroize::Zeroizing;

fn cases() -> Vec<Value> {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../testdata/protx_collateral.json"
    );
    let doc: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("golden file")).unwrap();
    assert_eq!(doc["network"], "regtest");
    let cases = doc["cases"].as_array().unwrap().clone();
    let kinds: Vec<&str> = cases.iter().map(|c| c["kind"].as_str().unwrap()).collect();
    assert_eq!(kinds, ["fund_new", "existing"]);
    cases
}

fn str_of<'a>(c: &'a Value, key: &str) -> &'a str {
    c[key]
        .as_str()
        .unwrap_or_else(|| panic!("{key} is missing"))
}

fn script_of(address: &str) -> ScriptBuf {
    Address::from_str(address)
        .unwrap()
        .require_network(Network::Regtest)
        .unwrap()
        .script_pubkey()
}

fn secret_of(wif: &str) -> Zeroizing<[u8; 32]> {
    let secret = dw_uri::keyio::decode_secret(wif, Network::Regtest).expect("regtest WIF");
    assert!(secret.compressed);
    secret.key
}

fn pro_reg_tx(c: &Value) -> (Transaction, ProviderRegistrationPayload) {
    let tx: Transaction =
        dashcore::consensus::deserialize(&hex::decode(str_of(c, "tx_hex")).unwrap()).unwrap();
    assert_eq!(tx.txid().to_string(), str_of(c, "pro_tx_hash"));
    let Some(TransactionPayload::ProviderRegistrationPayloadType(p)) =
        tx.special_transaction_payload.clone()
    else {
        panic!("not a ProRegTx");
    };
    (tx, p)
}

/// MG-00 D43: the collateral outpoint `protx info` reports, from the
/// payload's (a null hash names an output of the ProRegTx itself), and the
/// collateral output pays 1000 DASH to `collateralAddress`'s script.
#[test]
fn test_QT_123_collateral_outpoints_and_scripts_equal_dashd() {
    for c in cases() {
        let (tx, p) = pro_reg_tx(&c);
        let want = OutPoint {
            txid: Txid::from_str(str_of(&c, "collateral_hash")).unwrap(),
            vout: c["collateral_index"].as_u64().unwrap() as u32,
        };
        assert_eq!(resolve_collateral(tx.txid(), p.collateral_outpoint), want);
        let script = script_of(str_of(&c, "collateral_address"));
        match str_of(&c, "kind") {
            "fund_new" => {
                assert_eq!(p.collateral_outpoint.txid, Txid::all_zeros());
                assert_eq!(want.txid, tx.txid());
                let out = &tx.output[want.vout as usize];
                assert_eq!(out.script_pubkey, script);
                assert_eq!(out.value, MASTERNODE_COLLATERAL);
            }
            _ => {
                assert_eq!(p.collateral_outpoint, want);
                assert_eq!(
                    hex::encode(script.as_bytes()),
                    str_of(&c, "collateral_script_hex")
                );
                assert_eq!(
                    (c["collateral_value"].as_f64().unwrap() * 1e8).round() as u64,
                    MASTERNODE_COLLATERAL
                );
            }
        }
    }
}

/// The placeholder and finalizer rebuild dashd's payload byte for byte:
/// the inputs hash, the fund-new output index, and for an existing
/// collateral the `signmessage` signature (RFC 6979, no extra entropy).
#[test]
fn test_QT_123_rebuilt_registrations_equal_dashd() {
    for c in cases() {
        let (tx, p) = pro_reg_tx(&c);
        let fund_new = str_of(&c, "kind") == "fund_new";
        let collateral_script = script_of(str_of(&c, "collateral_address"));
        let terms = RegistrationTerms {
            evo: false,
            collateral: if fund_new {
                CollateralSource::FundNew {
                    script: collateral_script.clone(),
                    amount: MASTERNODE_COLLATERAL,
                }
            } else {
                CollateralSource::Existing(p.collateral_outpoint)
            },
            service: p.service_address,
            owner_key_hash: p.owner_key_hash.to_byte_array(),
            voting_key_hash: p.voting_key_hash.to_byte_array(),
            operator_public_key: parse_public_hex(str_of(&c, "operator_public")).unwrap(),
            operator_reward: p.operator_reward,
            payout_script: p.script_payout.clone(),
            platform: None,
        };
        let mut unsigned = tx.clone();
        unsigned.special_transaction_payload = Some(
            TransactionPayload::ProviderRegistrationPayloadType(registration_placeholder(&terms)),
        );
        let signer = if fund_new {
            RegistrationSigner::FundNew {
                script: collateral_script,
                amount: MASTERNODE_COLLATERAL,
            }
        } else {
            RegistrationSigner::Collateral {
                secret: secret_of(str_of(&c, "collateral_wif")),
                network: Network::Regtest,
            }
        };
        assert_eq!(
            finalize_registration(&unsigned, &signer).unwrap(),
            TransactionPayload::ProviderRegistrationPayloadType(p),
            "{} payload",
            str_of(&c, "kind")
        );
    }
}

/// `CProRegTx::MakeSignString` and the collateral key's signature over it.
#[test]
fn test_QT_123_collateral_sign_message_equals_dashd() {
    let c = cases().pop().unwrap();
    let (_, p) = pro_reg_tx(&c);
    let message = registration_sign_message(&p, Network::Regtest).unwrap();
    assert_eq!(message, str_of(&c, "sign_message"));
    let secret = secret_of(str_of(&c, "collateral_wif"));
    assert_eq!(
        hex::encode(sign_message_compact(&secret, &message).unwrap()),
        str_of(&c, "collateral_signature_hex")
    );
}

/// dashd's operator keys parse in the basic form, and `legacy_of` gives
/// `bls fromsecret <secret> true`'s public key.
#[test]
fn test_QT_124_operator_key_forms_equal_dashd() {
    for c in cases() {
        let basic = parse_public_hex(str_of(&c, "operator_public")).unwrap();
        let (_, p) = pro_reg_tx(&c);
        assert_eq!(p.operator_public_key.as_ref(), &basic);
        assert_eq!(
            hex::encode(legacy_of(&basic).unwrap()),
            str_of(&c, "operator_public_legacy")
        );
    }
}
